// Reusable SSH runner for .215 (server id cmsecmdps0001hlp27ai6mr7c).
// Decrypts server.rootPasswordEnc via the platform crypto-box, connects with
// ssh2, runs a command from argv, streams stdout/stderr. Password never echoed.
require("dotenv").config();
const { PrismaClient } = require("@prisma/client");
const { Client } = require("ssh2");
const { decryptSecret } = require("./lib/crypto-box");

const SERVER_ID = "cmsecmdps0001hlp27ai6mr7c";
const HOST = "51.79.226.215";

async function main() {
  const cmd = process.argv[2];
  if (!cmd) { console.error("no command"); process.exit(2); }
  const stdinData = process.env.SSH_STDIN || null;
  const p = new PrismaClient();
  const s = await p.server.findUnique({ where: { id: SERVER_ID }, include: { dedicatedIp: true } });
  await p.$disconnect();
  if (!s) { console.error("no server row"); process.exit(3); }
  const host = s.dedicatedIp?.address || HOST;
  const port = s.sshPort || 22;
  const password = decryptSecret(s.rootPasswordEnc) || s.rootPassword;
  if (!password) { console.error("no password"); process.exit(4); }
  const conn = new Client();
  conn.on("ready", () => {
    conn.exec(cmd, (err, stream) => {
      if (err) { console.error("EXEC ERR", err.message); conn.end(); process.exit(5); }
      let code = 0;
      stream.on("close", (c) => { code = c || 0; conn.end(); process.exit(code); });
      stream.on("data", (d) => process.stdout.write(d));
      stream.stderr.on("data", (d) => process.stderr.write(d));
      if (stdinData) { stream.write(stdinData); stream.end(); }
    });
  }).on("error", (e) => { console.error("CONN ERR", e.message); process.exit(6); })
    .connect({ host, port, username: "root", password, readyTimeout: 20000 });
}
main().catch((e) => { console.error("FATAL", e.message); process.exit(1); });

// TEMP helper (feature/website-suite build). Runs a command on .215 over ssh2.
// Decrypts server.rootPasswordEnc inline (AES-256-GCM, scrypt(AUTH_SECRET,"nxeon-byok")).
// Password is never printed. Delete when done.
const fs = require("fs");
const { PrismaClient } = require("@prisma/client");
const { Client } = require("ssh2");
const { createDecipheriv, scryptSync } = require("node:crypto");

// load .env
for (const line of fs.readFileSync(__dirname + "/.env", "utf8").split("\n")) {
  const m = line.match(/^([A-Z0-9_]+)=(.*)$/);
  if (m && !process.env[m[1]]) process.env[m[1]] = m[2].replace(/^["']|["']$/g, "");
}

function decryptSecret(enc) {
  if (!enc) return null;
  try {
    const key = scryptSync(process.env.AUTH_SECRET, "nxeon-byok", 32);
    const [iv, tag, data] = enc.split(":");
    const d = createDecipheriv("aes-256-gcm", key, Buffer.from(iv, "base64"));
    d.setAuthTag(Buffer.from(tag, "base64"));
    return Buffer.concat([d.update(Buffer.from(data, "base64")), d.final()]).toString("utf8");
  } catch { return null; }
}

const SERVER_ID = "cmsecmdps0001hlp27ai6mr7c";

async function main() {
  const cmd = process.argv[2];
  if (!cmd) { console.error("no command"); process.exit(2); }
  const stdinData = process.env.SSH_STDIN || null;
  const p = new PrismaClient();
