  const host = s.dedicatedIp?.address || "51.79.226.215";
  const port = s.sshPort || 22;
  const password = decryptSecret(s.rootPasswordEnc) || s.rootPassword;
  if (!password) { console.error("no password"); process.exit(4); }
  const conn = new Client();
  conn.on("ready", () => {
    conn.exec(cmd, (err, stream) => {
      if (err) { console.error("EXEC ERR", err.message); conn.end(); process.exit(5); }
      stream.on("close", (c) => { conn.end(); process.exit(c || 0); });
      stream.on("data", (d) => process.stdout.write(d));
      stream.stderr.on("data", (d) => process.stderr.write(d));
      if (stdinData) { stream.write(stdinData); stream.end(); }
    });
  }).on("error", (e) => { console.error("CONN ERR", e.message); process.exit(6); })
    .connect({ host, port, username: "root", password, readyTimeout: 20000 });
}
main().catch((e) => { console.error("FATAL", e.message); process.exit(1); });

