  const chosen = (preview && TEMPLATE_IDS.includes(preview as TemplateId) ? preview : w.template) as TemplateId;
  const Template = TEMPLATES[chosen] ?? Boutique;
  return <><TrackView slug={slug} /><Pixels policies={tenant.policies} />{Template(data)}<ChatWidget slug={slug} brand={tenant.brandColor || "#F97316"} studio={tenant.name} /><ZaloButton policies={tenant.policies} /></>;
