const fs = require("fs");
const { PrismaClient } = require("@prisma/client");
const { Client } = require("ssh2");
const { createDecipheriv, scryptSync } = require("node:crypto");
for (const line of fs.readFileSync(__dirname + "/.env", "utf8").split("\n")) {
  const m = line.match(/^([A-Z0-9_]+)=(.*)$/);
  if (m && !process.env[m[1]]) process.env[m[1]] = m[2].replace(/^["']|["']$/g, "");
}
function decryptSecret(enc) {
  const key = scryptSync(process.env.AUTH_SECRET, "nxeon-byok", 32);
  const [iv, tag, data] = enc.split(":");
  const d = createDecipheriv("aes-256-gcm", key, Buffer.from(iv, "base64"));
  d.setAuthTag(Buffer.from(tag, "base64"));
  return Buffer.concat([d.update(Buffer.from(data, "base64")), d.final()]).toString("utf8");
}
async function main() {
  const [local, remote] = process.argv.slice(2);
  if (!local || !remote) { console.error("usage: put <local> <remote>"); process.exit(2); }
  const content = fs.readFileSync(local);
  const b64 = content.toString("base64");
  const p = new PrismaClient();
  const s = await p.server.findUnique({ where: { id: "cmsecmdps0001hlp27ai6mr7c" }, include: { dedicatedIp: true } });
  await p.$disconnect();
  const password = decryptSecret(s.rootPasswordEnc);
  const dir = remote.replace(/\/[^/]*$/, "");
  const cmd = `mkdir -p '${dir}' && base64 -d > '${remote}' && echo WROTE ${remote}`;
  const conn = new Client();
  conn.on("ready", () => {
    conn.exec(cmd, (err, stream) => {
      if (err) { console.error(err.message); process.exit(5); }
      stream.on("close", (c) => { conn.end(); process.exit(c || 0); });
      stream.on("data", (d) => process.stdout.write(d));
      stream.stderr.on("data", (d) => process.stderr.write(d));
      stream.write(b64); stream.end();
    });
  }).on("error", (e) => { console.error(e.message); process.exit(6); })
    .connect({ host: s.dedicatedIp?.address || "51.79.226.215", port: s.sshPort || 22, username: "root", password, readyTimeout: 20000 });
}
